#ifndef LOOPI1_GENERIC_H
#define LOOPI1_GENERIC_H

#include <Loop.hpp>

extern "C" {
  extern complex qli1(double const& m1, double const& mu2, int const& ep);
  extern complex qli1c(complex const& m1, double const& mu2, int const& ep);
}

extern complex loopI1(double m1, double mu2, int ep);
extern complex loopI1(complex m1, double mu2, int ep);

#endif

#include <loopI1_generic.hpp>
#include <cmath>
#include <complex>
#include <iostream>
#include <scalarselect_mod.hpp>

using namespace scalarselect_mod;

complex loopI1(double m1, double mu2, int ep) {
  complex resQCDLoop, resOneLOop, loopI1_res;
  complex result[3];

  if (scalarselect == 1 || scalarselect == 3) {
    resQCDLoop = qli1(m1, mu2, ep);
  }

  if (scalarselect == 1) {
    loopI1_res = resQCDLoop;
    return loopI1_res;
  }

  if (scalarselect == 3) {
    if (std::abs(resOneLOop) > 1e-9 && std::abs(resQCDLoop / resOneLOop - 1.0) > 1e-9) {
      std::cout << "loopI1: " << m1 << ", " << ep << std::endl;
      std::cout << "QCDLoop: " << resQCDLoop << std::endl;
      std::cout << "OneLOop: " << resOneLOop << std::endl;
      std::cout << "->ratio: " << resQCDLoop / resOneLOop << std::endl;
    }
  }

  return loopI1_res;
}

complex loopI1(complex m1, double mu2, int ep) {
  complex resQCDLoop, resOneLOop, loopI1_res;
  complex result[3];

  if (scalarselect == 1 || scalarselect == 3) {
    resQCDLoop = qli1c(m1, mu2, ep);
  }

  if (scalarselect == 1) {
    loopI1_res = resQCDLoop;
    return loopI1_res;
  }

  resOneLOop = result[std::abs(ep)];
  loopI1_res = resOneLOop;

  if (scalarselect == 3) {
    if (std::abs(resOneLOop) > 1e-12 && std::abs(resQCDLoop / resOneLOop - 1.0) > 1e-12) {
      std::cout << "loopI1: " << m1 << ", " << ep << std::endl;
      std::cout << "QCDLoop: " << resQCDLoop << std::endl;
      std::cout << "OneLOop: " << resOneLOop << std::endl;
      std::cout << "->ratio: " << resQCDLoop / resOneLOop << std::endl;
    }
  }

  return loopI1_res;
}

extern "C" {
  complex loopI1_wrapper(double m1, double mu2, int ep) {
    return loopI1(m1, mu2, ep);
  }

  complex loopI1c_wrapper(complex m1, double mu2, int ep) {
    return loopI1(m1, mu2, ep);
  }
}
